{
     "AWSTemplateFormatVersion": "2010-09-09",
     "Description": "Creates one public subnet per availability zone.",
     "Resources": {
          "GreenPrivateUsEast1a": {
               "Type": "AWS::EC2::Subnet",
               "Properties": {
                    "MapPublicIpOnLaunch": false,
                    "VpcId": {"Fn::ImportValue": {"Fn::Join": [
                         "-",
                         [
                              {"Ref": "AWS::Region"},
                              "synapse-dev-vpc-2",
                              "VPCId"
                         ]
                    ]}},
                    "CidrBlock": "10.24.32.0/24",
                    "AvailabilityZone": "us-east-1a",
                    "Tags": [
                         {
                              "Key": "Application",
                              "Value": {"Ref": "AWS::StackName"}
                         },
                         {
                              "Key": "Name",
                              "Value": "GreenPrivateUsEast1a"
                         }
                    ]
               }
          },
          "GreenPrivateUsEast1aRouteTable": {
               "Type": "AWS::EC2::RouteTable",
               "Properties": {
                    "VpcId": {"Fn::ImportValue": {"Fn::Join": [
                         "-",
                         [
                              {"Ref": "AWS::Region"},
                              "synapse-dev-vpc-2",
                              "VPCId"
                         ]
                    ]}},
                    "Tags": [
                         {
                              "Key": "Application",
                              "Value": {"Ref": "AWS::StackName"}
                         },
                         {
                              "Key": "Name",
                              "Value": "GreenPrivateUsEast1a"
                         }
                    ]
               }
          },
          "GreenPrivateUsEast1aPrivateRoute": {
               "Type": "AWS::EC2::Route",
               "Properties": {
                    "RouteTableId": {"Ref": "GreenPrivateUsEast1aRouteTable"},
                    "DestinationCidrBlock": "0.0.0.0/0",
                    "NatGatewayId": {"Fn::ImportValue": {"Fn::Join": [
                         "-",
                         [
                              {"Ref": "AWS::Region"},
                              "synapse-dev-vpc-2-public-subnets",
                              "PublicUsEast1aNATGatway"
                         ]
