{
  "AWSTemplateFormatVersion": "2010-09-09",
  "Description": "Bootstrap template for creating a continuous integration user and permissions",
  "Resources": {
    "Bucket": {
      "Type": "AWS::S3::Bucket"
    },
    "CognitoRole": {
      "Type": "AWS::IAM::Role",
      "Properties": {
        "AssumeRolePolicyDocument": {
          "Version": "2012-10-17",
          "Statement": [
            {
              "Effect": "Allow",
              "Principal": {
                "Federated": "cognito-identity.amazonaws.com"
              },
              "Action": "sts:AssumeRoleWithWebIdentity",
              "Condition": {
                "StringEquals": {
                  "cognito-identity.amazonaws.com:aud": ""
                },
                "ForAnyValue:StringLike": {
                  "cognito-identity.amazonaws.com:amr": "authenticated"
                }
              }
            }
          ]
        }
      }
    },
    "CIPolicy": {
      "Type": "AWS::IAM::ManagedPolicy",
      "Properties": {
        "Description": "Policy for the CI User",
        "PolicyDocument": {
          "Version": "2012-10-17",
          "Statement": [
            {
              "Effect": "Allow",
              "Action": [
                "s3:DeleteObject",
                "s3:GetObject",
                "s3:PutObject"
              ],
              "Resource": {
                "Fn::Join": [
                  "",
                  [
                    "arn:aws:s3:::",
                    {
                      "Ref": "Bucket"
                    },
                    "/*"
                  ]
                ]
              }
            },
            {
              "Effect": "Allow",
              "Action": [
                "cognito-identity:CreateIdentityPool",
                "cognito-identity:DeleteIdentityPool",
                "cognito-identity:SetIdentityPoolRoles",
                "cognito-identity:UpdateIdentityPool"
              ],
              "Resource": {
                "Fn::Join": [
                  "",
                  [
                    "arn:aws:cognito-identity:",
                    {
                      "Ref": "AWS::Region"
                    },
                    ":",
                    {
                      "Ref": "AWS::AccountId"
                    },
                    ":identitypool/*"
                  ]
                ]
              }
            },
            {
              "Effect": "Allow",
              "Action": [
                "iam:PassRole"
              ],
              "Resource": {
                "Fn::GetAtt": [
                  "CognitoRole",
                  "Arn"
                ]
              }
            }
          ]
        }
      }
    },
    "CIUser": {
      "Type": "AWS::IAM::User",
      "DependsOn": [
        "CIPolicy"
      ],
      "Properties": {
        "Path": "/ci/",
        "ManagedPolicyArns": [
          {
            "Ref": "CIPolicy"
          }
        ]
      }
    },
    "CIUserAccessKey": {
      "Type": "AWS::IAM::AccessKey",
      "DependsOn": [
        "CIUser"
      ],
      "Properties": {
        "UserName": {
          "Ref": "CIUser"
        }
      }
    }
  },
  "Outputs": {
    "CIUserAccessKey": {
      "Value": {
        "Ref": "CIUserAccessKey"
      }
    },
    "CIUserSecretKey": {
      "Value": {
        "Fn::GetAtt": [
          "CIUserAccessKey",
          "SecretAccessKey"
        ]
      }
    },
    "CIRegion": {
      "Value": {
        "Ref": "AWS::Region"
      }
    },
    "Bucket": {
      "Value": {
        "Ref": "Bucket"
      }
    },
    "CognitoRole": {
      "Value": {
        "Fn::GetAtt": [
          "CognitoRole",
          "Arn"
        ]
      }
    }
  }
}

{
 "AWSTemplateFormatVersion": "2010-09-09",
 "Description": "Creates an AWS WAF configuration that protects against common attacks",
 "Parameters": {
  "WebACLName": {
   "Default": "CommonAttackProtection",
   "Description": "Enter the name you want to use for the WebACL. This value is also added as a prefix for the names of the rules, conditions, and CloudWatch metrics created by this template.",
   "Type": "String"
  }
 },
 "Resources": {
  "ManualIPBlockRule": {
   "Properties": {
    "MetricName": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "WebACLName"
       },
       "ManualIPBlockRule"
      ]
     ]
    },
    "Name": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "WebACLName"
       },
       "ManualIPBlockRule"
      ]
     ]
    },
    "Predicates": [
     {
      "DataId": {
       "Ref": "WAFManualIPBlockSet"
      },
      "Negated": false,
      "Type": "IPMatch"
     }
    ]
   },
   "Type": "AWS::WAF::Rule"
  },
  "MyWebACL": {
   "Properties": {
    "DefaultAction": {
     "Type": "ALLOW"
    },
    "MetricName": {
     "Ref": "WebACLName"
    },
    "Name": {
     "Ref": "WebACLName"
    },
    "Rules": [
     {
      "Action": {
       "Type": "BLOCK"
      },
      "Priority": 1,
      "RuleId": {
       "Ref": "ManualIPBlockRule"
      }
     },
     {
      "Action": {
       "Type": "COUNT"
      },
      "Priority": 2,
      "RuleId": {
       "Ref": "SizeMatchRule"
      }
     },
     {
      "Action": {
       "Type": "BLOCK"
      },
      "Priority": 3,
      "RuleId": {
       "Ref": "SqliRule"
      }
     },
     {
      "Action": {
       "Type": "BLOCK"
      },
      "Priority": 4,
      "RuleId": {
       "Ref": "XssRule"
      }
     }
    ]
   },
   "Type": "AWS::WAF::WebACL"
  },
  "SizeMatchRule": {
   "Properties": {
    "MetricName": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "WebACLName"
       },
       "DetectLargeBody"
      ]
     ]
    },
    "Name": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "WebACLName"
       },
       "LargeBodyMatchRule"
      ]
     ]
    },
    "Predicates": [
     {
      "DataId": {
       "Ref": "SizeMatchSet"
      },
      "Negated": false,
      "Type": "SizeConstraint"
     }
    ]
   },
   "Type": "AWS::WAF::Rule"
  },
  "SizeMatchSet": {
   "Properties": {
    "Name": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "WebACLName"
       },
       "LargeBodyMatch"
      ]
     ]
    },
    "SizeConstraints": [
     {
      "ComparisonOperator": "GT",
      "FieldToMatch": {
       "Type": "BODY"
      },
      "Size": "8192",
      "TextTransformation": "NONE"
     }
    ]
   },
   "Type": "AWS::WAF::SizeConstraintSet"
  },
  "SqliMatchSet": {
   "Properties": {
    "Name": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "WebACLName"
       },
       "SqliMatch"
      ]
     ]
    },
    "SqlInjectionMatchTuples": [
     {
      "FieldToMatch": {
       "Type": "QUERY_STRING"
      },
      "TextTransformation": "URL_DECODE"
     },
     {
      "FieldToMatch": {
       "Type": "QUERY_STRING"
      },
      "TextTransformation": "HTML_ENTITY_DECODE"
     },
     {
      "FieldToMatch": {
       "Type": "BODY"
      },
      "TextTransformation": "URL_DECODE"
     },
     {
      "FieldToMatch": {
       "Type": "BODY"
      },
      "TextTransformation": "HTML_ENTITY_DECODE"
     },
     {
      "FieldToMatch": {
       "Type": "URI"
      },
      "TextTransformation": "URL_DECODE"
     }
    ]
   },
   "Type": "AWS::WAF::SqlInjectionMatchSet"
  },
  "SqliRule": {
   "Properties": {
    "MetricName": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "WebACLName"
       },
       "SqliRule"
      ]
     ]
    },
    "Name": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "WebACLName"
       },
       "SqliRule"
      ]
     ]
    },
    "Predicates": [
     {
      "DataId": {
       "Ref": "SqliMatchSet"
      },
      "Negated": false,
      "Type": "SqlInjectionMatch"
     }
    ]
   },
   "Type": "AWS::WAF::Rule"
  },
  "WAFManualIPBlockSet": {
   "Properties": {
    "Name": "Manual IP Block Set"
   },
   "Type": "AWS::WAF::IPSet"
  },
  "XssMatchSet": {
