                "PublicSubnetAZ1": "172.19.0.0/22"
            },
            "172.20.0.0": {
                "PublicSubnetAZ1": "172.20.0.0/22"
            },
            "172.21.0.0": {
                "PublicSubnetAZ1": "172.21.0.0/22"
            },
            "172.22.0.0": {
                "PublicSubnetAZ1": "172.22.0.0/22"
            },
