{
 "AWSTemplateFormatVersion": "2010-09-09",
 "Description": "Creates an AWS WAF configuration that protects against common attacks",
 "Parameters": {
  "WebACLName": {
   "Default": "CommonAttackProtection",
   "Description": "Enter the name you want to use for the WebACL. This value is also added as a prefix for the names of the rules, conditions, and CloudWatch metrics created by this template.",
   "Type": "String"
  }
 },
 "Resources": {
  "ManualIPBlockRule": {
   "Properties": {
    "MetricName": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "WebACLName"
       },
       "ManualIPBlockRule"
      ]
     ]
    },
    "Name": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "WebACLName"
       },
       "ManualIPBlockRule"
      ]
     ]
    },
    "Predicates": [
     {
      "DataId": {
       "Ref": "WAFManualIPBlockSet"
      },
      "Negated": false,
      "Type": "IPMatch"
     }
    ]
   },
   "Type": "AWS::WAFRegional::Rule"
  },
  "MyWebACL": {
   "Properties": {
    "DefaultAction": {
     "Type": "ALLOW"
    },
    "MetricName": {
     "Ref": "WebACLName"
    },
    "Name": {
     "Ref": "WebACLName"
    },
    "Rules": [
     {
      "Action": {
       "Type": "BLOCK"
      },
      "Priority": 1,
      "RuleId": {
       "Ref": "ManualIPBlockRule"
      }
     },
     {
      "Action": {
       "Type": "COUNT"
      },
      "Priority": 2,
      "RuleId": {
       "Ref": "SizeMatchRule"
      }
     },
     {
      "Action": {
       "Type": "BLOCK"
      },
      "Priority": 3,
      "RuleId": {
       "Ref": "SqliRule"
      }
     },
     {
      "Action": {
       "Type": "BLOCK"
      },
      "Priority": 4,
      "RuleId": {
       "Ref": "XssRule"
      }
     }
    ]
   },
   "Type": "AWS::WAFRegional::WebACL"
  },
  "SizeMatchRule": {
   "Properties": {
    "MetricName": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "WebACLName"
       },
       "DetectLargeBody"
      ]
     ]
    },
    "Name": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "WebACLName"
       },
       "LargeBodyMatchRule"
      ]
     ]
    },
    "Predicates": [
     {
      "DataId": {
       "Ref": "SizeMatchSet"
      },
      "Negated": false,
      "Type": "SizeConstraint"
     }
    ]
   },
   "Type": "AWS::WAFRegional::Rule"
  },
  "SizeMatchSet": {
   "Properties": {
    "Name": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "WebACLName"
       },
       "LargeBodyMatch"
      ]
     ]
    },
    "SizeConstraints": [
     {
      "ComparisonOperator": "GT",
      "FieldToMatch": {
       "Type": "BODY"
      },
      "Size": "8192",
      "TextTransformation": "NONE"
     }
    ]
   },
   "Type": "AWS::WAFRegional::SizeConstraintSet"
  },
  "SqliMatchSet": {
   "Properties": {
    "Name": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "WebACLName"
       },
       "SqliMatch"
      ]
     ]
    },
    "SqlInjectionMatchTuples": [
     {
      "FieldToMatch": {
       "Type": "QUERY_STRING"
      },
      "TextTransformation": "URL_DECODE"
     },
     {
      "FieldToMatch": {
       "Type": "QUERY_STRING"
      },
      "TextTransformation": "HTML_ENTITY_DECODE"
     },
     {
      "FieldToMatch": {
       "Type": "BODY"
      },
      "TextTransformation": "URL_DECODE"
     },
     {
      "FieldToMatch": {
       "Type": "BODY"
      },
      "TextTransformation": "HTML_ENTITY_DECODE"
     },
     {
      "FieldToMatch": {
       "Type": "URI"
      },
      "TextTransformation": "URL_DECODE"
     }
    ]
   },
   "Type": "AWS::WAFRegional::SqlInjectionMatchSet"
  },
  "SqliRule": {
   "Properties": {
    "MetricName": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "WebACLName"
       },
       "SqliRule"
      ]
     ]
    },
    "Name": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "WebACLName"
       },
       "SqliRule"
      ]
     ]
    },
    "Predicates": [
     {
      "DataId": {
       "Ref": "SqliMatchSet"
      },
      "Negated": false,
      "Type": "SqlInjectionMatch"
     }
    ]
   },
   "Type": "AWS::WAFRegional::Rule"
  },
  "WAFManualIPBlockSet": {
   "Properties": {
    "Name": "Manual IP Block Set"
   },
   "Type": "AWS::WAFRegional::IPSet"
  },
  "XssMatchSet": {
   "Properties": {
    "Name": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "WebACLName"
       },
       "XssMatch"
      ]
     ]
    },
    "XssMatchTuples": [
     {
      "FieldToMatch": {
       "Type": "QUERY_STRING"
      },
      "TextTransformation": "URL_DECODE"
     },
     {
      "FieldToMatch": {
       "Type": "QUERY_STRING"
      },
      "TextTransformation": "HTML_ENTITY_DECODE"
     },
     {
      "FieldToMatch": {
       "Type": "BODY"
      },
      "TextTransformation": "URL_DECODE"
     },
     {
      "FieldToMatch": {
       "Type": "BODY"
      },
      "TextTransformation": "HTML_ENTITY_DECODE"
     },
     {
      "FieldToMatch": {
       "Type": "URI"
      },
      "TextTransformation": "URL_DECODE"
     }
    ]
   },
   "Type": "AWS::WAFRegional::XssMatchSet"
  },
  "XssRule": {
   "Properties": {
    "MetricName": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "WebACLName"
       },
       "XssRule"
      ]
     ]
    },
    "Name": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "WebACLName"
       },
       "XssRule"
      ]
     ]
    },
    "Predicates": [
     {
      "DataId": {
       "Ref": "XssMatchSet"
      },
      "Negated": false,
      "Type": "XssMatch"
     }
    ]
   },
   "Type": "AWS::WAFRegional::Rule"
  }
 }
}

{
  "AWSTemplateFormatVersion":"2010-09-09",
  "Description":"Credstash KMS key and DynamoDB",
  "Metadata":{
    "Source":"https://github.com/mozilla/security/tree/master/operations/cloudformation-templates",
  },
  "Resources":{
    "KMSKey":{
      "Type" : "AWS::KMS::Key",
      "Properties" : {
        "Description" : "Credstash customer master key",
        "KeyPolicy" : {
          "Version": "2012-10-17",
          "Statement": [{
            "Sid": "Enable IAM User Permissions",
            "Effect": "Allow",
            "Principal": {"AWS": {"Fn::Join":["",["arn:aws:iam::",{"Ref":"AWS::AccountId"},":root"]]}},
            "Action": "kms:*",
            "Resource": "*"
          }]
        }
      }
    },
    "KMSKeyAlias": {
      "Type" : "AWS::KMS::Alias",
      "Properties" : {
        "AliasName" : "alias/credstash",
        "TargetKeyId" : {"Ref":"KMSKey"}
      }
    },
    "CredentialStore":{
      "Type" : "AWS::DynamoDB::Table",
      "Properties" : {
        "TableName" : "credential-store",
        "AttributeDefinitions" : [
          {
            "AttributeName": "name",
            "AttributeType": "S"
          },
          {
            "AttributeName": "version",
            "AttributeType": "S"
          }
        ],
        "KeySchema" : [
          {
            "AttributeName": "name",
            "KeyType": "HASH"
          },
          {
            "AttributeName": "version",
            "KeyType": "RANGE"
          }
        ],
        "ProvisionedThroughput" : {
          "ReadCapacityUnits": 1,
          "WriteCapacityUnits": 1
        }
      }
    }
  }
}

{
 "Description": "AWS CloudFormation Sample Template NatGateway: Sample template showing how to create a public NAT gateway. **WARNING** This template creates an Amazon NAT gateway. You will be billed for the AWS resources used if you create a stack from this template.",
 "Outputs": {
  "NatEip": {
   "Description": "Nat Elastic IP",
   "Value": {
    "Ref": "NatEip"
   }
  },
  "VPCId": {
   "Description": "VPC Id",
   "Value": {
    "Ref": "VPC"
   }
  }
 },
 "Parameters": {
  "PrivateSubnetCidr": {
   "Default": "172.18.32.0/21",
   "Description": "Public Subnet CIDR",
   "Type": "String"
  },
  "PublicSubnetCidr": {
   "Default": "172.18.0.0/22",
   "Description": "Public Subnet CIDR",
   "Type": "String"
  },
  "VPCCIDR": {
   "Default": "172.18.0.0/16",
   "Description": "The IP address space for this VPC, in CIDR notation",
   "Type": "String"
  }
 },
 "Resources": {
  "InternetGateway": {
   "Type": "AWS::EC2::InternetGateway"
  },
  "Nat": {
   "Properties": {
    "AllocationId": {
     "Fn::GetAtt": [
      "NatEip",
      "AllocationId"
     ]
    },
    "SubnetId": {
     "Ref": "PublicSubnet"
    }
   },
   "Type": "AWS::EC2::NatGateway"
  },
  "NatAttachment": {
   "Properties": {
    "InternetGatewayId": {
     "Ref": "InternetGateway"
    },
    "VpcId": {
     "Ref": "VPC"
    }
   },
   "Type": "AWS::EC2::VPCGatewayAttachment"
  },
  "NatEip": {
   "Properties": {
    "Domain": "vpc"
   },
   "Type": "AWS::EC2::EIP"
  },
  "NatRoute": {
   "Properties": {
    "DestinationCidrBlock": "0.0.0.0/0",
    "NatGatewayId": {
     "Ref": "Nat"
    },
    "RouteTableId": {
     "Ref": "PrivateRouteTable"
    }
   },
   "Type": "AWS::EC2::Route"
  },
  "PrivateRouteAssociation": {
   "Properties": {
    "RouteTableId": {
     "Ref": "PrivateRouteTable"
    },
    "SubnetId": {
     "Ref": "PrivateSubnet"
    }
   },
   "Type": "AWS::EC2::SubnetRouteTableAssociation"
  },
  "PrivateRouteTable": {
   "Properties": {
    "VpcId": {
     "Ref": "VPC"
    }
   },
   "Type": "AWS::EC2::RouteTable"
  },
  "PrivateSubnet": {
   "Properties": {
    "CidrBlock": {
     "Ref": "PrivateSubnetCidr"
    },
    "MapPublicIpOnLaunch": false,
    "VpcId": {
     "Ref": "VPC"
    }
   },
   "Type": "AWS::EC2::Subnet"
  },
  "PublicDefaultRoute": {
   "Properties": {
    "DestinationCidrBlock": "0.0.0.0/0",
    "GatewayId": {
     "Ref": "InternetGateway"
    },
    "RouteTableId": {
     "Ref": "PublicRouteTable"
    }
   },
   "Type": "AWS::EC2::Route"
  },
  "PublicRouteAssociation": {
   "Properties": {
    "RouteTableId": {
     "Ref": "PublicRouteTable"
    },
    "SubnetId": {
     "Ref": "PublicSubnet"
    }
   },
   "Type": "AWS::EC2::SubnetRouteTableAssociation"
  },
  "PublicRouteTable": {
   "Properties": {
    "VpcId": {
     "Ref": "VPC"
    }
   },
   "Type": "AWS::EC2::RouteTable"
  },
  "PublicSubnet": {
   "Properties": {
    "CidrBlock": {
     "Ref": "PublicSubnetCidr"
    },
    "MapPublicIpOnLaunch": true,
    "VpcId": {
     "Ref": "VPC"
    }
   },
   "Type": "AWS::EC2::Subnet"
  },
  "VPC": {
   "Properties": {
    "CidrBlock": {
     "Ref": "VPCCIDR"
    }
   },
   "Type": "AWS::EC2::VPC"
  }
 }
}

