{
  "AWSTemplateFormatVersion" : "2010-09-09",

  "Description" : "Build an AWS VPC with one or more public subnets in differents AZs.",

  "Parameters" : {

    "SubnetCount": {
      "Description": "Number of subnets [1,2,3]; defaults to single public subnet",
      "Type": "Number",
      "MinValue": "1",
      "MaxValue": "3",
      "Default": "1",
      "AllowedValues": [
        "1", "2", "3"
      ]
    }
  },

  "Mappings" : {

  },

  "Conditions": {

    "CreateSubnet02": { "Fn::Or" : [
      { "Fn::Equals" : [ "2", { "Ref": "SubnetCount" } ] },
      { "Fn::Equals" : [ "3", { "Ref": "SubnetCount" } ] }
    ]},
    "CreateSubnet03": { "Fn::Equals" : [ "3", { "Ref": "SubnetCount" } ] }
  },

  "Resources" : {

    "VPC" : {
      "Type" : "AWS::EC2::VPC",
      "Properties" : {
        "CidrBlock" : "192.168.0.0/16",
        "EnableDnsSupport" : true,
        "EnableDnsHostnames" : true,
        "Tags" : [
          {"Key" : "Name", "Value" : { "Ref" : "AWS::StackName"} },
          {"Key" : "Application", "Value" : { "Ref" : "AWS::StackName"} },
          {"Key" : "Network", "Value" : "Public" }
        ]
      }
    },

    "PublicSubnet01" : {
      "Type" : "AWS::EC2::Subnet",
      "Properties" : {
        "VpcId" : { "Ref" : "VPC" },
        "CidrBlock" : "192.168.1.0/24",
        "AvailabilityZone": { "Fn::Select": [ "0", { "Fn::GetAZs": "" } ] },
        "Tags" : [
          {"Key" : "Name", "Value" : { "Fn::Join" : [ "-", [ { "Ref" : "AWS::StackName"}, "Subnet01" ] ] }},
          {"Key" : "Application", "Value" : { "Ref" : "AWS::StackName"} },
          {"Key" : "Network", "Value" : "Public" }
        ]
      }
    },

    "PublicSubnet02" : {
      "Type" : "AWS::EC2::Subnet",
      "Condition": "CreateSubnet02",
      "Properties" : {
        "VpcId" : { "Ref" : "VPC" },
        "CidrBlock" : "192.168.2.0/24",
        "AvailabilityZone": { "Fn::Select": [ "1", { "Fn::GetAZs": "" } ] },
        "Tags" : [
          {"Key" : "Name", "Value" : { "Fn::Join" : [ "-", [ { "Ref" : "AWS::StackName"}, "Subnet02" ] ] }},
          {"Key" : "Application", "Value" : { "Ref" : "AWS::StackName"} },
          {"Key" : "Network", "Value" : "Public" }
        ]
      }
    },

    "PublicSubnet03" : {
      "Type" : "AWS::EC2::Subnet",
      "Condition": "CreateSubnet03",
      "Properties" : {
        "VpcId" : { "Ref" : "VPC" },
        "CidrBlock" : "192.168.3.0/24",
        "AvailabilityZone": { "Fn::Select": [ "2", { "Fn::GetAZs": "" } ] },
        "Tags" : [
          {"Key" : "Name", "Value" : { "Fn::Join" : [ "-", [ { "Ref" : "AWS::StackName"}, "Subnet03" ] ] }},
          {"Key" : "Application", "Value" : { "Ref" : "AWS::StackName"} },
          {"Key" : "Network", "Value" : "Public" }
        ]
      }
    },

    "InternetGateway" : {
      "Type" : "AWS::EC2::InternetGateway",
      "Properties" : {
        "Tags" : [
          {"Key" : "Application", "Value" : { "Ref" : "AWS::StackName"} },
          {"Key" : "Network", "Value" : "Public" }
        ]
      }
    },

    "AttachGateway" : {
      "Type" : "AWS::EC2::VPCGatewayAttachment",
      "Properties" : {
         "VpcId" : { "Ref" : "VPC" },
         "InternetGatewayId" : { "Ref" : "InternetGateway" }
      }
    },

    "PublicRouteTable" : {
      "Type" : "AWS::EC2::RouteTable",
      "Properties" : {
        "VpcId" : {"Ref" : "VPC"},
        "Tags" : [
          {"Key" : "Application", "Value" : { "Ref" : "AWS::StackName"} },
          {"Key" : "Network", "Value" : "Public" }
        ]
      }
    },

    "PublicRoute" : {
      "Type" : "AWS::EC2::Route",
      "Properties" : {
        "RouteTableId" : { "Ref" : "PublicRouteTable" },
        "DestinationCidrBlock" : "0.0.0.0/0",
        "GatewayId" : { "Ref" : "InternetGateway" }
      }
    },

    "PublicSubnet01RouteTableAssociation" : {
      "Type" : "AWS::EC2::SubnetRouteTableAssociation",
      "Properties" : {
        "SubnetId" : { "Ref" : "PublicSubnet01" },
        "RouteTableId" : { "Ref" : "PublicRouteTable" }
      }
    },

    "PublicSubnet02RouteTableAssociation" : {
      "Type" : "AWS::EC2::SubnetRouteTableAssociation",
      "Condition": "CreateSubnet02",
      "Properties" : {
        "SubnetId" : { "Ref" : "PublicSubnet02" },
        "RouteTableId" : { "Ref" : "PublicRouteTable" }
      }
    },

    "PublicSubnet03RouteTableAssociation" : {
      "Type" : "AWS::EC2::SubnetRouteTableAssociation",
      "Condition": "CreateSubnet03",
      "Properties" : {
        "SubnetId" : { "Ref" : "PublicSubnet03" },
        "RouteTableId" : { "Ref" : "PublicRouteTable" }
      }
    }
  },

  "Outputs" : {

    "VpcId" : {
      "Value" : {"Ref" : "VPC"},
      "Description" : "VPC ID of newly created VPC"
    },

    "MainSubnetId" : {
      "Value" : { "Ref" : "PublicSubnet01" },
      "Description" : "Main default subnet ID"
    },

    "SubnetIds" : {
      "Value" : {
        "Fn::If" : [
          "CreateSubnet03",
          { "Fn::Join" : [", ", [
            { "Ref" : "PublicSubnet01" },
            { "Ref" : "PublicSubnet02" },
            { "Ref" : "PublicSubnet03" }
          ]]},
          { "Fn::If" : [
              "CreateSubnet02",
              { "Fn::Join" : [", ", [
                { "Ref" : "PublicSubnet01" },
                { "Ref" : "PublicSubnet02" }
              ]]},
              { "Ref" : "PublicSubnet01" }
            ]
          }
        ]
      },
      "Description" : "Comma-separated list of all public subnet IDs across different AZs"
    }
  }
}

AWSTemplateFormatVersion: "2010-09-09"
Transform: AWS::Serverless-2016-10-31

Description: >
  Infrastructure as code for authorization layer (Amazon Verified Permissions and Cedar policies).

Resources:

  PolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    Properties:
      Description: Final version of the Cedar policy store that will be recreated independently.
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "actions": {
                "View": {
                  "appliesTo": {
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "required": true,
                          "name": "region",
                          "type": "String"
                        }
                      }
                    },
                    "principalTypes": [
                      "User"
                    ]
                  },
                  "memberOf": []
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "required": true,
                          "type": "String",
                          "name": "region"
                        }
                      }
                    },
                    "resourceTypes": [
                      "Book"
                    ]
                  },
                  "memberOf": []
                }
              },
              "entityTypes": {
                "Role": {
                  "memberOfTypes": [],
                  "shape": {
                    "type": "Record",
                    "attributes": {}
                  }
                },
                "User": {
                  "memberOfTypes": [
                    "Role"
                  ],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long",
                        "required": false
                      }
                    }
                  }
                },
                "Book": {
                  "memberOfTypes": [],
                  "shape": {
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "required": true,
                        "name": "User"
                      }
                    },
                    "type": "Record"
                  }
                }
              }
            }
          }

  PolicyStoreIdSSM:
    Type: AWS::SSM::Parameter
    Properties:
      Type: String
      Name: /bookstore-demo-app-with-authz/authorization/policy-store-id
      Value: !Ref PolicyStore

  RbacAdminStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Allows admins to list all books"
          Statement: |
            permit (
              principal in Bookstore::Role::"Admin",
              action in [ Bookstore::Action::"View" ],
              resource
            );

  RbacAdminForbidStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Denies admin Frank to list all books"
          Statement: |
            forbid (
              principal == Bookstore::User::"Frank",
              action in [ Bookstore::Action::"View" ],
              resource
            );

  RbacResourceOwnerStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Allows publishers to list books they have published"
          Statement: |
            permit (
              principal in Bookstore::Role::"Publisher",
              action in [ Bookstore::Action::"View" ],
              resource
            )
            when {
              principal == resource.owner
            };

  RbacExplicitStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Allows specific Publisher to list a specific book"
          Statement: |
            permit (
              principal == Bookstore::User::"Dante",
              action in [ Bookstore::Action::"View" ],
              resource == Bookstore::Book::"em1oadaa-b22k-4ea8-kk33-f6m217604o3m"
            );

  PermitAbacStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Allows customers with specific value for yearsAsMember attribute to list premium offers"
          Statement: |
            permit (
              principal in Bookstore::Role::"Customer",
              action in [ Bookstore::Action::"ViewWithPremiumOffers" ],
              resource
            )
            when { principal has yearsAsMember && principal.yearsAsMember >= 2 };

  DenyAbacStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Denies customers with specific value for yearsAsMember attribute to list premium offers"
          Statement: |
            forbid (
              principal in Bookstore::Role::"Customer",
              action in [ Bookstore::Action::"ViewWithPremiumOffers" ],
              resource
            )
            when { principal has yearsAsMember && principal.yearsAsMember < 2 };

  ContextStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Denies access for users outside the US region"
          Statement: |
            forbid (
              principal,
              action in [ Bookstore::Action::"View", Bookstore::Action::"ViewWithPremiumOffers" ],
              resource
            )
            when { context.region != "US" };

Outputs:

  PolicyStoreId:
    Description: "Identifier of the Amazon Verified Permissions policy store."
    Value: !Ref PolicyStore

